# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe InvoicePayment::StripePaymentSucceeded, "under the billing fence" do
  let(:company) { create(:company, base_currency: "USD") }
  let(:client) { create(:client, company:, currency: "USD") }
  let!(:invoice) do
    create(
      :invoice,
      company:,
      client:,
      currency: "USD",
      status: "sent",
      amount: 100,
      amount_due: 100,
      amount_paid: 0,
      payment_infos: { "stripe_payment_intent" => "pi_fence_123" }
    )
  end
  let(:event) do
    OpenStruct.new(
      id: "evt_fence_123",
      created: Time.current.to_i,
      data: OpenStruct.new(
        object: OpenStruct.new(id: "pi_fence_123", amount_received: 10_000, amount: 10_000, currency: "usd")
      )
    )
  end

  before do
    allow(PaymentMailer).to receive_message_chain(:with, :payment, :deliver_later)
    allow_any_instance_of(Invoice).to receive(:send_to_client_email)
  end

  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  # Its StandardError rescue returns nil today; swallowing the refusal would answer the provider with
  # success and lose the customer's payment.
  it "lets a refused Stripe payment event escape and records it exactly once when replayed after the handoff" do
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    expect {
      expect { described_class.process(event) }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    }.not_to change(Payment, :count)
    expect(invoice.reload).not_to be_paid

    TimekeepingOwnership.current.update!(handoff_step: nil)

    expect { described_class.process(event) }.to change(Payment, :count).by(1)
    expect { described_class.process(event) }.not_to change(Payment, :count)
    expect(invoice.reload).to be_paid
  end
end
